#nullable enable // autogenerated

using System;
using PVZEngine;
using UnityEngine;

namespace MVZ2Logic.Models.Widgets
{
    public class AnimatorSoundPlayer : MonoBehaviour
    {
        public void PlaySound(string name)
        {
            foreach (var item in soundItems)
            {
                if (item.name != name)
                    continue;
                var id = item.soundID?.Get();
                if (NamespaceID.IsValid(id))
                {
                    Global.Sounds.Play2D(id);
                }
                break;
            }
        }
        [SerializeField]
        private AnimatorSoundPlayerItem[] soundItems = null!;
    }
    [Serializable]
    public class AnimatorSoundPlayerItem
    {
        public string name = "";
        public NamespaceIDReference? soundID;
    }
}
